const scenario = $env.SENTINELA_PILOT_SCENARIO || $json.scenario || 'health';
const base = {
  health: { method: 'GET', path: '/api/v1/health', auth: false },
  probe: { method: 'GET', path: '/api/v1/protected-probe' },
  identify: { method: 'GET', path: '/api/v1/residents/identify?name=Maria%20Pilot&unit=101' },
  package: {
    method: 'POST',
    path: '/api/v1/operations/packages',
    body: {
      recipient: 'G7-H-B-N8N-TEST',
      unit: '101',
      type: 'caixa',
      input_type: 'text',
      text: 'pilot package G7-H-B-N8N-TEST',
      metadata: { source: 'n8n-pilot', gate: 'G7-H-B' }
    },
    idempotencyKey: `n8n-g7hb-${Date.now()}`
  },
  pickup: {
    method: 'POST',
    path: '/api/v1/operations/packages/pickup',
    body: { resource_id: 'pkg-missing-pilot' }
  }
};
const cfg = base[scenario] || base.health;
return [{ json: { scenario, ...cfg, baseUrl: $env.SENTINELA_PILOT_BASE || 'http://127.0.0.1:3099' } }];

const method = String($json.method || 'GET').toUpperCase();
const pathWithQuery = String($json.path || '/api/v1/health');
const bodyObj = $json.body;
const body =
  bodyObj === undefined || bodyObj === null
    ? ''
    : typeof bodyObj === 'string'
      ? bodyObj
      : JSON.stringify(bodyObj);
const idempotencyKey = String($json.idempotencyKey || '');
const baseUrl = String($json.baseUrl || $env.SENTINELA_PILOT_BASE || 'http://127.0.0.1:3099');
const requestId = String($json.requestId || `n8n-${Date.now()}`);

if ($json.auth === false) {
  return [
    {
      json: {
        ...$json,
        method,
        path: pathWithQuery,
        body,
        url: `${baseUrl}${pathWithQuery}`,
        headers: { 'X-Request-Id': requestId },
        meta: { canonical_version: 'v1', auth: false }
      }
    }
  ];
}

const nodeCrypto = require('crypto');
const secret = $env.SENTINELA_N8N_SECRET || $env.SENTINELA_HARNESS_SECRET;
const clientId = $env.SENTINELA_N8N_CLIENT_ID || $env.SENTINELA_HARNESS_CLIENT_ID;
const org = $env.SENTINELA_N8N_ORGANIZATION_ID || $env.SENTINELA_HARNESS_ORG;
const condo = $env.SENTINELA_N8N_CONDOMINIUM_ID || $env.SENTINELA_HARNESS_CONDO;

if (!secret || !clientId || !org || !condo) {
  throw new Error('Missing Sentinela n8n credential env vars');
}

const timestamp = String(Math.floor(Date.now() / 1000));
const bodySha = nodeCrypto.createHash('sha256').update(body).digest('hex');
const canonical = ['v1', timestamp, method, pathWithQuery, bodySha, org, condo, idempotencyKey].join('\n');
const signature = nodeCrypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');

return [
  {
    json: {
      ...$json,
      method,
      path: pathWithQuery,
      body,
      url: `${baseUrl}${pathWithQuery}`,
      headers: {
        'X-Sentinela-Client-Id': clientId,
        'X-Sentinela-Timestamp': timestamp,
        'X-Sentinela-Signature': signature,
        'X-Organization-Id': org,
        'X-Condominium-Id': condo,
        'X-Request-Id': requestId,
        ...(idempotencyKey ? { 'Idempotency-Key': idempotencyKey } : {}),
        ...(body ? { 'Content-Type': 'application/json' } : {})
      },
      meta: { canonical_version: 'v1', body_sha256: bodySha }
    }
  }
];

const body = $json;
const requestId = body.request_id || null;
const success = body.success === true;
const errorCode = body.error && body.error.code ? body.error.code : null;
const core = body.data && body.data.core_executed;
const sanitized = JSON.stringify(body);
if (/service_role|BEGIN |password=|confirmation_token/i.test(sanitized) && errorCode !== 'CONFIRMATION_REQUIRED') {
  // CONFIRMATION_REQUIRED may include one-shot token in details by contract — flag only secrets
}
return [{ json: {
  ok: success || !!errorCode,
  request_id: requestId,
  success,
  error_code: errorCode,
  core_executed: core ?? null,
  operation: body.operation || (body.data && body.data.operation) || null,
  note: 'Validate envelope only — do not log headers/signature/secret'
}}];
